parameters.text:
=You are an expert customer support AI. Analyze the customer's message and return ONLY a valid JSON object. Do not include markdown formatting or conversational text.

Required JSON structure:
{
  "category": "complaint | question | sales",
  "sentiment": "positive | neutral | negative",
  "priority": "High | Medium | Low",
  "language": "detected language code (e.g. RU, PL, EN)",
  "auto_reply_subject": "Write 'We received your message' in detected language",
  "auto_reply": "Write a short, polite auto-reply message thanking the customer for their inquiry, WRITTEN IN THEIR ORIGINAL LANGUAGE. If it's a complaint, apologize for the inconvenience."
}

Customer Name: {{ $json.body.name }}
Customer Message: {{ $json.body.message }}

parameters.jsCode:
// The classifier is told to return raw JSON, but models occasionally wrap it in
// a markdown fence or add a sentence of commentary. Strip the fence, then validate.
//
// This node guards an outbound email to a customer, so the bar is higher than in
// scenario 1. A malformed classification must stop the run here rather than send
// an empty or nonsensical auto-reply: a failed execution is an internal problem,
// a bad auto-reply is a public one.

const raw = $input.first().json.text ?? '';
const cleaned = raw.replace(/```json/gi, '').replace(/```/g, '').trim();

let analysis;
try {
  analysis = JSON.parse(cleaned);
} catch (err) {
  throw new Error(
    `Classifier did not return valid JSON. Raw output:\n${cleaned.slice(0, 500)}`
  );
}

const required = [
  'category', 'sentiment', 'priority', 'language', 'auto_reply_subject', 'auto_reply',
];
const missing = required.filter((f) => !analysis[f]);
if (missing.length) {
  throw new Error(`Classification is missing required fields: ${missing.join(', ')}`);
}

// The model picks from a closed set. Anything outside it is a hallucinated label
// that would silently produce mis-routed tickets — cheap to catch, expensive to miss.
const allowed = {
  category: ['complaint', 'question', 'sales'],
  sentiment: ['positive', 'neutral', 'negative'],
  priority: ['High', 'Medium', 'Low'],
};
for (const [field, values] of Object.entries(allowed)) {
  if (!values.includes(analysis[field])) {
    throw new Error(
      `Unexpected ${field}: "${analysis[field]}". Allowed: ${values.join(', ')}`
    );
  }
}

// The webhook is public, so its payload is untrusted input, not a given.
const request = $('Webhook: incoming request').first().json.body ?? {};
for (const field of ['name', 'email', 'message']) {
  if (!request[field]) {
    throw new Error(`Webhook payload is missing required field: ${field}`);
  }
}

return [{ json: { request, ai_analysis: analysis } }];
